      "enabled": true,
      "source": "original-v7",
      "kind": "story",
      "category": "story_observation",
      "text": "我有一次去剪頭髮。\n理髮師問我：「今天想怎麼剪？」\n我說：「短一點就好。」\n他點頭，很專業。\n剪完之後，他拿鏡子給我看。\n我看了三秒，說：「好像比我想像中短。」\n他很淡定地說：「你剛才說短一點。」\n我說：「對。」\n他說：「所以我把『一點』處理掉了。」",
      "friendIds": [
        "ahsiung-story"
      ],
      "tags": [
        "長篇純笑話"
      ],
