      "source": "original-v7",
      "kind": "story",
      "category": "story_observation",
      "text": "我朋友第一次去健身房，回來非常興奮。\n我問：「今天練了什麼？」\n他說：「很多。」\n我追問：「腿？胸？背？」\n他說：「主要是研究器材。」\n我說：「你有練嗎？」\n他想了想。\n「有。」\n「哪一個？」\n「跑步機。」\n「跑多久？」\n「三分鐘。」\n我說：「那也不錯。」\n他說：「不是，我是用三分鐘走到那台機器旁邊。」",
      "friendIds": [
        "ahsiung-story"
      ],
