      "title": "咖啡店的安靜",
      "text": "我去咖啡店讀書，特地找了一個最安靜的角落。\n坐下來以後，我打開電腦，深呼吸，準備開始。\n隔壁桌突然小聲說：「不好意思，你有看到我的筆嗎？」\n我轉過頭。\n他又問：「你是不是有看到我的筆？」\n我說沒有。\n他點點頭：「好，謝謝。」\n五分鐘後，他又問同一句。\n我忍不住說：「我真的沒有看到。」\n他說：「我知道，我只是想確認你還在不在。」",
